<template>
  <v-main class="p-3">
    <NavBar />

    <div class="row py-5 px-3">
      <div class="col-md-7 col-xs-12 col-sm-12">
        <h1 class="py-5 mobile-big-font">12.25 Brunch Order Counter</h1>
      </div>
    </div>

    <div class="row py-3 px-3 justify-content-center">
      <div class="col-md-8 col-xs-12">
        <!-- FOOD SELECTION -->
        <div
          v-for="(item, index) in foodItems"
          :key="index"
          class="food-item-card mb-4 p-4"
        >
          <div class="d-flex justify-content-between align-items-center">
            <h4>{{ item.emoji }} {{ item.name }}</h4>
            <div class="d-flex align-items-center">
              <v-btn
                color="error"
                elevation="2"
                @click="decrementCount(index)"
                :disabled="item.count === 0"
              >
                −
              </v-btn>
              <span class="count-display px-4">{{ item.count }}</span>
              <v-btn
                color="primary"
                elevation="2"
                @click="incrementCount(index)"
              >
                +
              </v-btn>
            </div>
          </div>
        </div>

        <!-- NAME + SUBMIT -->
        <v-text-field v-model="userName" label="Your name" class="mt-4" />

        <v-btn color="success" block class="mt-2" @click="submitOrder">
          Submit Order ✅
        </v-btn>

        <!-- CONFIRMED ORDERS -->
        <div class="mt-10">
          <h3>Confirmed Orders</h3>

          <div
            v-for="order in confirmedOrders"
            :key="order.id"
            class="food-item-card p-3 mb-3"
          >
            <div class="d-flex justify-content-between align-items-start">
              <div>
                <strong>{{ order.name }}</strong>
                <ul class="mt-2">
                  <li v-for="item in order.items" :key="item.name">
                    {{ item.emoji }} {{ item.name }} × {{ item.count }}
                  </li>
                </ul>
              </div>

              <v-btn icon color="error" @click="deleteOrder(order.id)">
                ❌
              </v-btn>
            </div>
          </div>
        </div>

        <!-- TOTALS -->
        <div class="mt-10 total-section p-4">
          <h3>🔥 Total to Prepare</h3>
          <ul>
            <li v-for="(item, name) in totals" :key="name">
              {{ item.emoji }} {{ name }}:
              <strong>{{ item.count }}</strong>
            </li>
          </ul>
        </div>
      </div>
    </div>
  </v-main>
</template>

<script>
import NavBar from "@/components/ui_components/NavBar.vue";
import { db } from "@/firebase/config";
import {
  collection,
  addDoc,
  onSnapshot,
  deleteDoc,
  doc,
} from "firebase/firestore";

export default {
  name: "FoodOrderPage",
  components: { NavBar },

  data() {
    return {
      userName: "",
      confirmedOrders: [],
      unsubscribe: null,

      foodItems: [
        { emoji: "🥓🥑", name: "培根牛油果班尼迪克蛋", count: 0 },
        { emoji: "🫐", name: "混合莓果松饼", count: 0 },
        { emoji: "🍚", name: "卤肉饭", count: 0 },
        { emoji: "🥣", name: "皮蛋瘦肉粥", count: 0 },
        { emoji: "☕", name: "手冲咖啡 (红醋栗、可可和葡萄酒风味)", count: 0 },
        { emoji: "🍵", name: "Infusion Tea", count: 0 },
        {
          emoji: "🍰🦃",
          name: "A weird cake, might be a turkey or chicken leg, you don't need to order this because I will make one for you anyways.",
          count: 0,
        },
      ],
    };
  },

  computed: {
    totals() {
      const result = {};

      this.confirmedOrders.forEach((order) => {
        order.items.forEach((item) => {
          if (!result[item.name]) {
            result[item.name] = {
              emoji: item.emoji,
              count: 0,
            };
          }
          result[item.name].count += item.count;
        });
      });

      return result;
    },
  },

  mounted() {
    this.subscribeToOrders();
  },

  beforeUnmount() {
    if (this.unsubscribe) this.unsubscribe();
  },

  methods: {
    incrementCount(index) {
      this.foodItems[index].count++;
    },

    decrementCount(index) {
      if (this.foodItems[index].count > 0) {
        this.foodItems[index].count--;
      }
    },

    async submitOrder() {
      if (!this.userName.trim()) {
        alert("Please enter your name 🥺");
        return;
      }

      const selectedItems = this.foodItems.filter((i) => i.count > 0);
      if (selectedItems.length === 0) {
        alert("You didn’t select any food 👀");
        return;
      }

      await addDoc(collection(db, "orders"), {
        name: this.userName,
        items: selectedItems,
        createdAt: new Date(),
      });

      this.foodItems.forEach((i) => (i.count = 0));
      this.userName = "";
    },

    subscribeToOrders() {
      this.unsubscribe = onSnapshot(collection(db, "orders"), (snapshot) => {
        this.confirmedOrders = snapshot.docs.map((doc) => ({
          id: doc.id,
          ...doc.data(),
        }));
      });
    },

    async deleteOrder(orderId) {
      if (!confirm("Delete this order?")) return;
      await deleteDoc(doc(db, "orders", orderId));
    },
  },
};
</script>

<style scoped>
.food-item-card {
  background-color: #f5f5f5;
  border-radius: 8px;
  border: 1px solid #e0e0e0;
}

.count-display {
  font-size: 1.5rem;
  font-weight: bold;
  min-width: 60px;
  text-align: center;
}

.total-section {
  background-color: #e3f2fd;
  border-radius: 8px;
  border: 2px solid #2196d2;
}
</style>
