import { createRouter, createWebHistory } from "vue-router";
import HomePage from "../components/HomePage.vue";
import MePage from "../components/MePage.vue";
import WorkPage from "../components/WorkPage.vue";
import FunPage from "@/components/FunPage.vue";
import WritingPage from "@/components/WritingPage.vue";
import twentySixPage from "@/components/writing/26.vue";
import DesignPrompt from "@/components/DesignPrompt.vue";
import FusAIn from "@/components/FusAIn.vue";
import food from "@/components/food.vue";
import DesignTrace from "@/components/DesignTrace.vue";
import RevisitInstrument from "@/components/RevisitInstrument.vue";
import ResearchStatement from "@/components/ResearchStatement.vue";
const routes = [
  { path: "/", component: HomePage, name: "HomePage" },
  { path: "/work", component: WorkPage, name: "WorkPage" },
  { path: "/fun", component: FunPage, name: "FunPage" },
  { path: "/me", component: MePage, name: "MePage" },
  { path: "/writing", component: WritingPage, name: "writing" },
  { path: "/writing/26", component: twentySixPage, name: "26" },
  { path: "/how-to-use-dp", component: DesignPrompt, name: "DesignPrompt" },
  { path: "/how-to-use-fusain", component: FusAIn, name: "FusAIn" },
  { path: "/how-to-use-dt", component: DesignTrace, name: "DesignTrace" },
  { path: "/order-food", component: food, name: "food" },
  {
    path: "/revisit-instrument",
    component: RevisitInstrument,
    name: "RevisitInstrument",
  },
  {
    path: "/research-statement",
    component: ResearchStatement,
    name: "ResearchStatement",
  },
];
const router = createRouter({
  history: createWebHistory(),
  routes,

  scrollBehavior(to, from, savedPosition) {
    if (savedPosition) {
      return savedPosition;
    }

    return { top: 0 };
  },
});

export default router;
